retirement_microbenchmark.source:
//! Disposable benchmark of the existing retirement operation on unrelated Oops.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::size;
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let host = oop::bootstrap();
    let q = host.scope();
    let source = q.string(b"[[:captured | [| captured]] value: 41]").unwrap();
    let block = q.call(host.named(b"Codegen").unwrap(), b"eval:", &[source]).unwrap();
    q.check_result(block).unwrap();
    let expected = q.call(block, b"value", &[]).unwrap();
    let word = q.call(host.named(b"Integer").unwrap(), b"wordOf:", &[expected]).unwrap();
    assert_eq!(q.word_bits(word).unwrap(), 41);
    let behavior = q.call(host.id.root, b"objectBehavior", &[]).unwrap();
    let allocate = q.keep(host.intern(b"allocate").unwrap()).unwrap();
    let mut objects = Vec::new();
    for _ in 0..65536 {
        objects.push(q.keep(unsafe { host.id.send(behavior, allocate, &[size(0).unwrap()]).unwrap() }).unwrap());
    }
    q.call(host.named(b"GC").unwrap(), b"collectPrecisely", &[]).unwrap();
    let identity = q.call(host.id.root, b"identityOf:", &[objects[0]]).unwrap();
    let receiver = host.named(b"Execution").unwrap();
    let selector = q.keep(host.intern(b"retire:").unwrap()).unwrap();
    for (count, repeats) in [(0, 10000), (1, 20000), (1024, 512), (65536, 8)] {
        let args = &objects[..count];
        for _ in 0..3 { assert!(unsafe { host.id.send(receiver, selector, args).unwrap() }.is_null()); }
        for _ in 0..5 {
            let start = unsafe { clock_gettime_nsec_np(16) };
            for _ in 0..repeats {
                assert!(unsafe { host.id.send(receiver, selector, args).unwrap() }.is_null());
            }
            println!("{count} {repeats} {}", unsafe { clock_gettime_nsec_np(16) } - start);
        }
        assert_eq!(q.call(block, b"value", &[]).unwrap(), expected);
        assert_eq!(q.call(host.id.root, b"identityOf:", &[objects[0]]).unwrap(), identity);
    }
}

